import threading

def reproduce(connect, service) -> str | None:
    # Discover accounts and group by household.
    try:
        with connect() as conn:
            rows = conn.execute("SELECT id, balance FROM accounts ORDER BY id").fetchall()
    except Exception:
        return None
    households = {}
    for _id, _bal in rows:
        h = (_id + 1) // 2
        households.setdefault(h, []).append((_id, _bal))
    targets = []
    for h in sorted(households):
        accts = households[h]
        if len(accts) != 2:
            continue
        combined = sum(b for _, b in accts)
        if combined > 0:
            targets.append((h, accts[0][0], accts[1][0], combined))
        if len(targets) >= 8:
            break
    if not targets:
        return None
    for h, a1, a2, combined in targets:
        amount = combined
        barrier = threading.Barrier(2)
        def do_withdraw(aid):
            try:
                with connect() as conn:
                    try:
                        barrier.wait(timeout=5)
                    except Exception:
                        return
                    try:
                        service.withdraw(conn, aid, amount)
                    except Exception:
                        pass
            except Exception:
                pass
        t1 = threading.Thread(target=do_withdraw, args=(a1,))
        t2 = threading.Thread(target=do_withdraw, args=(a2,))
        t1.start()
        t2.start()
        t1.join(timeout=10)
        t2.join(timeout=10)
    try:
        with connect() as conn:
            bad = conn.execute(
                "SELECT household, SUM(balance) FROM accounts GROUP BY household HAVING SUM(balance) < 0"
            ).fetchall()
    except Exception:
        return None
    if bad:
        hh, s = bad[0][0], bad[0][1]
        return f"household {hh} overdrawn: combined balance {s} < 0 (joint overdraft rule broken)"
    return None
